<script lang="ts">
  /**
   * The Livingood badge from the studio's business card: a white disc in a
   * yellow ring, "LIVINGOOD WELLNESS CENTER" set round it as glyph outlines
   * (so no font is needed), and the watercolour butterfly in the middle: a
   * mirrored pair of wings on a thin body, tilted like the card; each side
   * is one continuous silhouette with scalloped margins and faint veins. The left side runs from a dark orange forewing tip through
   * yellow, green and aqua into blue and a deep-blue hindwing; the right
   * side from teal through cyan and blue into a lavender-and-magenta
   * hindwing. Every colour is fixed, including the dark body and antennae,
   * so the mark looks the same on every background and in both themes.
   * Decorative by default; pass a `label` when it stands alone.
   */
  interface Props {
    class?: string;
    label?: string;
  }

  let { class: className, label }: Props = $props();

  // Gradient and wing ids must be unique per instance, since the logo is
  // rendered several times on one page.
  const uid = $props.id();
</script>

